import{_ as t,o as a,c as l,a2 as o}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"作品閲覧 & ビューア詳細","description":"イラスト・マンガ・小説・うごイラ・ショートフィードの表示仕様および設定","frontmatter":{"title":"作品閲覧 & ビューア詳細","description":"イラスト・マンガ・小説・うごイラ・ショートフィードの表示仕様および設定"},"headers":[],"relativePath":"features/browse.md","filePath":"features/browse.md","lastUpdated":1786168778000}'),i={name:"features/browse.md"};function r(n,e,s,d,c,g){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="作品閲覧-ビューア詳細" tabindex="-1">作品閲覧 &amp; ビューア詳細 <a class="header-anchor" href="#作品閲覧-ビューア詳細" aria-label="Permalink to &quot;作品閲覧 &amp; ビューア詳細&quot;">​</a></h1><p>Palleria は多様なメディア表現（静止画、マルチページ、Zip アニメーション、文章コンテンツ、縦スワイプフィード）に対応した専用ビューアを搭載しています。</p><hr><h2 id="画面およびフィード構成" tabindex="-1">画面およびフィード構成 <a class="header-anchor" href="#画面およびフィード構成" aria-label="Permalink to &quot;画面およびフィード構成&quot;">​</a></h2><h3 id="_1-ホームタブ一覧" tabindex="-1">1. ホームタブ一覧 <a class="header-anchor" href="#_1-ホームタブ一覧" aria-label="Permalink to &quot;1. ホームタブ一覧&quot;">​</a></h3><ul><li><strong>おすすめ (Home)</strong>: アルゴリズムに基づく推奨作品の一覧。</li><li><strong>フォロー中</strong>: フォロー中ユーザーの新着投稿タイムライン。</li><li><strong>ランキング (<code>RankingScreen</code>)</strong>: <ul><li>デイリー (Daily) / ウィークリー (Weekly) / マンスリー (Monthly)</li><li>ルーキー (Rookie) / 男子人気 (Male) / 女子人気 (Female)</li><li>R-18 デイリー / R-18 ウィークリー / R-18G</li></ul></li><li><strong>ショートフィード (<code>ShortsFeedScreen</code>)</strong>: フルスクリーン縦スワイプによる作品流し読み機能。</li><li><strong>小説 (<code>NovelScreen</code>)</strong>: 小説の検索・シリーズ作品一覧・リーダー画面。</li></ul><hr><h2 id="各ビューアの詳細仕様" tabindex="-1">各ビューアの詳細仕様 <a class="header-anchor" href="#各ビューアの詳細仕様" aria-label="Permalink to &quot;各ビューアの詳細仕様&quot;">​</a></h2><h3 id="_1-イラスト・マンガビューア-imageviewerscreen" tabindex="-1">1. イラスト・マンガビューア (<code>ImageViewerScreen</code>) <a class="header-anchor" href="#_1-イラスト・マンガビューア-imageviewerscreen" aria-label="Permalink to &quot;1. イラスト・マンガビューア (`ImageViewerScreen`)&quot;">​</a></h3><ul><li><strong>ズーム &amp; 移動</strong>: Pinch-to-zoom、ダブルタップズーム、ドラッグ移動。</li><li><strong>見開き / 単ページ切り替え</strong>: <code>mangaReaderMode</code> (<code>paged</code> / <code>continuous</code> / <code>webtoon</code>)。</li><li><strong>画質設定パラメータ (<code>AppSettings</code>)</strong>: 画質はネットワーク負荷と表示精細度のバランスに合わせて個別に調整可能です。</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">設定項目名</th><th style="text-align:left;">選択値</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>feedPreviewQuality</code></td><td style="text-align:left;"><code>low</code> / <code>high</code></td><td style="text-align:left;">フィードリスト上のサムネイル画像解像度</td></tr><tr><td style="text-align:left;"><code>illustDetailQuality</code></td><td style="text-align:left;"><code>medium</code> / <code>high</code> / <code>original</code></td><td style="text-align:left;">イラスト詳細画面でのメイン表示画像解像度</td></tr><tr><td style="text-align:left;"><code>mangaDetailQuality</code></td><td style="text-align:left;"><code>low</code> / <code>high</code> / <code>original</code></td><td style="text-align:left;">マンガページ閲覧時の解像度</td></tr><tr><td style="text-align:left;"><code>fullscreenQuality</code></td><td style="text-align:left;"><code>high</code> / <code>original</code></td><td style="text-align:left;">フルスクリーン拡大ビューアでの解像度</td></tr></tbody></table><hr><h3 id="_2-うごイラ再生-ugoiraartwork" tabindex="-1">2. うごイラ再生 (<code>UgoiraArtwork</code>) <a class="header-anchor" href="#_2-うごイラ再生-ugoiraartwork" aria-label="Permalink to &quot;2. うごイラ再生 (`UgoiraArtwork`)&quot;">​</a></h3><p>うごイラ（アニメーションイラスト）は、Zip 圧縮された連続フレーム画像とミリ秒単位の遅延配列 (<code>UgoiraFrame</code>) で構成されています。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [ Ugoira Metadata Request ] ──&gt; Zip URL &amp; Frame Delay List ([{file: &quot;000000.jpg&quot;, delay: 125}, ...])</span></span>\n<span class="line"><span>                                         │</span></span>\n<span class="line"><span> [ Async Zip Download ] ───────&gt; Memory Unzip &amp; Cache</span></span>\n<span class="line"><span>                                         │</span></span>\n<span class="line"><span> [ Canvas Re-render Engine ] &lt;── Frame Timing Scheduler (Coroutine Loop)</span></span></code></pre></div><ul><li><strong>非同期解凍・キャッシュ</strong>: Zip アーカイブをダウンローダーで取得し、メモリ上で展開。</li><li><strong>再生制御</strong>: 再生 / 一時停止、ループ無効化、フレーム単位のステップ送り。</li><li><strong>エクスポート機能</strong>: APNG / GIF / MP4 フォーマットへの変換保存対応。</li></ul><hr><h3 id="_3-小説リーダー-novelscreen" tabindex="-1">3. 小説リーダー (<code>NovelScreen</code>) <a class="header-anchor" href="#_3-小説リーダー-novelscreen" aria-label="Permalink to &quot;3. 小説リーダー (`NovelScreen`)&quot;">​</a></h3><ul><li><strong>縦書き / 横書き表示</strong>: 日本語小説に適した縦書きレイアウト表示（右から左へのページ推移）に対応。</li><li><strong>リーダーカスタマイズ</strong>: <ul><li><code>appFont</code>: システムフォントまたはカスタム明朝/ゴシック体</li><li>フォントサイズ (sp)、行間倍率、余白幅の動的調整</li><li>テーマ設定（ホワイト / セピア / ダーク / ブラック）</li></ul></li><li><strong>挿絵表示</strong>: 文中に埋め込まれた <code>[pixivimage:illust_id-page]</code> タグを自動検出・インライン表示し、タップで拡大ポップアップ表示。</li></ul><hr><h2 id="ユーザープロフィール-userprofilescreen" tabindex="-1">ユーザープロフィール (<code>UserProfileScreen</code>) <a class="header-anchor" href="#ユーザープロフィール-userprofilescreen" aria-label="Permalink to &quot;ユーザープロフィール (`UserProfileScreen`)&quot;">​</a></h2><p>作者詳細画面では以下のデータが表示・操作可能です。</p><ul><li>投稿作品タブ（イラスト / マンガ / 小説 / シリーズ）</li><li>公開ブックマーク作品一覧</li><li>プロファイル情報（自己紹介文、外部 Web / SNS リンク）</li><li><strong>フォロー管理</strong>: 公開フォロー (<code>Restrict.Public</code>) / 非公開フォロー (<code>Restrict.Private</code>)</li><li><strong>ミュート管理</strong>: このユーザーをミュートリスト (<code>mutedUsers</code>) に登録</li></ul>',23)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
